<template>
  <el-dialog title="批量关联标准快递" :visible.sync="visible" width="1200px" append-to-body :close-on-click-modal="false">
    <p>当前范围：{{scope.provider}} · {{labels[scope.purpose]}}。候选只作提示，逐行选择标准快递后，先检查再确认。</p>
    <el-alert v-if="mappingRule" :title="mappingRule.label+'：'+mappingRule.description" type="info" :closable="false"/>
    <el-alert v-if="error||preferredError" :title="error||preferredError" type="error" :closable="false"/><el-button v-if="preferredError" type="text" @click="loadPreferred">重新核对提交或下发候选</el-button>
    <el-table :key="scope.system_type+':'+scope.purpose" :data="rows" max-height="470" size="small"><el-table-column :label="terms.item" min-width="190"><template slot-scope="{row}"><strong>{{row.external_name}}</strong><p>{{row.external_code}}</p></template></el-table-column><el-table-column label="选择 OMS 标准快递" min-width="300"><template slot-scope="{row}"><carrier-select v-model="row.standard_id" standard-only/><p class="hint">候选：<el-button v-for="c in row.candidates" :key="c.id" type="text" size="mini" @click="row.standard_id=c.id">{{c.standard_name}}</el-button><span v-if="!row.candidates.length">暂无，请搜索选择</span></p></template></el-table-column><el-table-column label="业务用途" width="160"><template slot-scope="{row}"><span v-if="mappingRule">{{mappingRule.label}}</span><span v-else>用途待核实</span></template></el-table-column><el-table-column v-if="showPreferredColumn" key="preferred-output" :label="scope.system_type==='CHANNEL'?'平台提交首选项':'仓库下发首选项'" width="150"><template slot-scope="{row}"><el-switch v-if="row.output_choices>1" v-model="row.is_default" :active-value="1" :inactive-value="0" :disabled="preferredLoading" @change="choosePreferred(row)"/><span v-else class="hint">仅此一个标识</span><p v-if="row.other_default" class="hint">已配首选：{{row.other_default}}</p></template></el-table-column><el-table-column v-if="scope.system_type==='WMS'" key="product-condition" label="运输产品编码" width="180"><template slot-scope="{row}"><el-input v-model="row.product_code" maxlength="64" placeholder="留空作为通用匹配"/></template></el-table-column><el-table-column v-if="preview" key="row-check" label="检查结果" min-width="190"><template slot-scope="{row,$index}"><span :class="preview.rows[$index].status==='ERROR'?'error':'hint'">{{preview.rows[$index].message||'检查通过'}}</span></template></el-table-column></el-table>
    <p v-if="scope.system_type==='WMS'" class="hint">运输产品编码按仓库约定填写：优先匹配业务传入的编码，未命中专用配置时使用留空的通用配置。</p>
    <el-form label-width="160px" class="evidence"><el-form-item label="配置来源与确认说明" required>
      <el-input v-model="evidence" type="textarea" :rows="3" :placeholder="'例如：依据'+terms.source+'提供的快递清单，已核对本批编码与标准快递的对应关系；清单版本或确认记录：____。'" maxlength="1000" show-word-limit/>
      <p class="hint">本说明适用于本批全部关联，请填写实际核对来源。</p>
    </el-form-item></el-form>
    <template v-if="preview"><p>检查 {{preview.rows.length}} 行，错误 {{preview.errors}} 行。确认后才建立标准快递关联。</p></template>
    <span slot="footer"><el-button :disabled="busy" @click="visible=false">关闭</el-button><el-button :loading="busy" @click="check">检查本批关联</el-button><el-button type="primary" :loading="busy" :disabled="!preview||!!Number(preview.errors)||confirmed" @click="confirm">{{confirmed?'已建立关联':'确认建立关联'}}</el-button></span>
  </el-dialog>
</template>
<script>
import CarrierSelect from '@/components/CarrierSelect'
import { mappingSuggestions, mappingBatchPreview, mappingBatchConfirm, mappingOutputOptions } from '@/api/common/carriers'
import { purposeLabels } from './CarrierScope'
import { carrierMappingRule } from '@/utils/carrierMappingPurpose'
import { carrierTerms } from '@/utils/carrierTerms'
import { outputPreferences } from '@/utils/carrierOutputPreferences'
const fields=['system_type','provider','purpose','connection_id','shop_id','owner_code','real_store_code']
export default {
 computed:{preferredKey(){return this.visible&&this.mappingRule&&this.mappingRule.direction==='OUT'?JSON.stringify([this.scope,this.rows.map(r=>[r.standard_id,r.product_code])]):''},showPreferredColumn(){return this.mappingRule&&this.mappingRule.direction==='OUT'&&this.rows.some(r=>r.output_choices>1)},terms(){return carrierTerms(this.scope.system_type)},mappingRule(){return carrierMappingRule(this.scope)}},components:{CarrierSelect},data:()=>({visible:false,busy:false,error:'',scope:{},preferredLoading:false,preferredError:'',preferredEpoch:0,preferredTimer:null,rows:[],evidence:'',preview:null,confirmed:false,labels:purposeLabels}),beforeDestroy(){this.preferredEpoch++;clearTimeout(this.preferredTimer)},watch:{preferredKey(){this.loadPreferred()},rows:{deep:true,handler(){this.preview=null;this.confirmed=false}},evidence(){this.preview=null;this.confirmed=false}},
 methods:{choosePreferred(row){if(!row.is_default)return;this.rows.forEach(other=>{if(other!==row&&String(other.standard_id)===String(row.standard_id)&&(other.product_code||'')===(row.product_code||''))other.is_default=0})},batchInput(){return {...this.scope,evidence:this.evidence,rows:this.rows.map(({directory_id,standard_id,direction,is_default,product_code,enabled})=>({directory_id,standard_id,direction,is_default,product_code,enabled}))}},loadPreferred(){clearTimeout(this.preferredTimer);const epoch=++this.preferredEpoch;this.preferredLoading=false;this.preferredError='';const selected=this.rows.filter(r=>r.standard_id);if(!this.preferredKey||!selected.length)return;this.preferredLoading=true;this.preferredTimer=setTimeout(async()=>{try{const result=(await mappingOutputOptions({...this.scope,items:selected.map(r=>({id:0,standard_id:r.standard_id,product_code:r.product_code||''}))})).data;if(epoch!==this.preferredEpoch||!this.visible)return;const preferences=outputPreferences(selected,result.rows);selected.forEach((r,i)=>{this.$set(r,'output_choices',preferences[i].choices);this.$set(r,'other_default',preferences[i].defaultCode);r.is_default=preferences[i].preferred})}catch(e){if(epoch===this.preferredEpoch)this.preferredError=e.message||'提交或下发候选查询失败，请重试'}finally{if(epoch===this.preferredEpoch)this.preferredLoading=false}},250)},async open(directories){this.error='';this.rows=[];this.evidence='';this.preview=null;this.confirmed=false;this.scope=Object.fromEntries(fields.map(k=>[k,directories[0][k]||'']));if(directories.some(d=>fields.some(k=>(d[k]||'')!==this.scope[k])))return this.$message.warning('请在同一系统、用途和适用范围内选择快递条目后批量关联');this.visible=true;this.busy=true;try{const rows=(await mappingSuggestions(directories.map(d=>d.id))).data;this.rows=rows.map(r=>({directory_id:r.directory.id,external_code:r.directory.external_code,external_name:r.directory.external_name,candidates:r.candidates,standard_id:'',direction:(carrierMappingRule(this.scope)||{}).direction||'IN',is_default:0,product_code:'',enabled:1,output_choices:0,other_default:''}))}catch(e){this.error=e.message||'候选资料查询失败'}finally{this.busy=false}},async check(){if(this.busy)return;if(!String(this.evidence||'').trim()){this.error='请填写配置来源与确认说明';return;}if(this.preferredLoading||this.preferredError){this.error=this.preferredError||'请等待提交或下发候选核对完成';return;}this.busy=true;this.error='';try{const input=this.batchInput(),fingerprint=JSON.stringify(input),result=(await mappingBatchPreview(input)).data;if(fingerprint!==JSON.stringify(this.batchInput())){this.preview=null;this.error='关联内容已变化，请按当前内容重新检查';return;}this.preview=result}catch(e){this.error=e.message||'批量检查失败'}finally{this.busy=false}},async confirm(){if(this.busy||!this.preview||this.confirmed)return;this.busy=true;try{await mappingBatchConfirm(this.preview.request_key);this.confirmed=true;this.$message.success('本批标准快递关联已保存');this.$emit('changed')}catch(e){this.error=e.message||'批量确认失败'}finally{this.busy=false}}}
}
</script>
<style scoped>.hint{font-size:12px;color:#7b899b;line-height:1.8}.hint .el-button{margin-left:6px}.evidence{margin-top:16px}.error{color:#d94a4a}</style>
